// bench1h in Java over primitive double: the two literals hoisted into locals
// bound once before the loop, the accumulator a primitive local.
public class Bench1HPrim {
    public static void main(String[] args) {
        double a = 0.9999999, b = 0.0000001, acc = 0.0;
        long t0 = System.nanoTime();
        for (int i = 1; i <= 20000000; i++) acc = acc * a + b;
        long t1 = System.nanoTime();
        System.out.println("bench1h " + acc);
        System.out.println("loop_ns " + (t1 - t0));
    }
}
EOF
cat > Bench1HBoxed.java <<'EOF'
// bench1h in Java over the runtime's box: the two literal boxes made once
// before the loop, one fresh box per arithmetic result inside it (two per
// iteration), accumulator a boxed local.  The JIT may scalar-replace the
// results; Bench1HBoxedSink is the same loop with escape analysis defeated.
public class Bench1HBoxed {
    public static void main(String[] args) {
        Box a = Box.make(0.9999999), b = Box.make(0.0000001), acc = Box.make(0.0);
        long t0 = System.nanoTime();
        for (int i = 1; i <= 20000000; i++) acc = Box.add(Box.mul(acc, a), b);
        long t1 = System.nanoTime();
        System.out.println("bench1h " + acc.getValue());
        System.out.println("loop_ns " + (t1 - t0));
    }
}
EOF
cat > Bench1HBoxedSink.java <<'EOF'
// bench1h boxed with escape analysis defeated: the accumulator box is stored
// through a volatile field, as com.sun.fortress.compiler.runtimeValues.
// MutableFValue.value is, so the JIT cannot scalar-replace the allocations.
// The honest upper bracket on what boxing alone costs.
public class Bench1HBoxedSink {
    static volatile Box cell;
    public static void main(String[] args) {
        Box a = Box.make(0.9999999), b = Box.make(0.0000001);
        cell = Box.make(0.0);
        long t0 = System.nanoTime();
        for (int i = 1; i <= 20000000; i++) cell = Box.add(Box.mul(cell, a), b);
        long t1 = System.nanoTime();
        System.out.println("bench1h " + cell.getValue());
        System.out.println("loop_ns " + (t1 - t0));
    }
}
EOF
