// kernel (a) over primitive double[]: 4192-element dot product, 200 reps.
public class KDotPrim {
    public static void main(String[] args) {
        int n = 4192, reps = 200;
        double[] x = new double[n], y = new double[n];
        for (int i = 0; i < n; i++) { x[i] = (i % 17 + 1) / 17.0; y[i] = (i % 23 + 1) / 23.0; }
        double s = 0.0;
        long t0 = System.nanoTime();
        for (int r = 0; r < reps; r++) { double d = 0.0; for (int i = 0; i < n; i++) d += x[i] * y[i]; s += d; }
        long t1 = System.nanoTime();
        System.out.println("kdot " + s);
        System.out.println("loop_ns " + (t1 - t0));
    }
}
EOF
cat > KDotBoxed.java <<'EOF'
// kernel (a) over an array of the runtime's boxes: Box[] storage, one fresh
// box per multiply and per add, as CompilerBuiltin's arithmetic does.
public class KDotBoxed {
    public static void main(String[] args) {
        int n = 4192, reps = 200;
        Box[] x = new Box[n], y = new Box[n];
        for (int i = 0; i < n; i++) { x[i] = Box.make((i % 17 + 1) / 17.0); y[i] = Box.make((i % 23 + 1) / 23.0); }
        Box s = Box.make(0.0);
        long t0 = System.nanoTime();
        for (int r = 0; r < reps; r++) {
            Box d = Box.make(0.0);
            for (int i = 0; i < n; i++) d = Box.add(d, Box.mul(x[i], y[i]));
            s = Box.add(s, d);
        }
        long t1 = System.nanoTime();
        System.out.println("kdot " + s.getValue());
        System.out.println("loop_ns " + (t1 - t0));
    }
}
EOF
