        for (int r = 0; r < reps; r++) out = rows(m);
        long t1 = System.nanoTime();
        System.out.println("krows " + out[0] + " " + out[N * N - 1]);
        System.out.println("loop_ns " + (t1 - t0));
    }
    static double[] rows(double[] m) {
        double[] out = new double[N * N];
        for (int i = 0; i < N; i++) {
            double[] y = rmsn(m, i * N);
            for (int j = 0; j < N; j++) out[i * N + j] = y[j];
        }
        return out;
    }
